import base64
import hashlib
import json
import runpy
import sys

import pytest

import bcrypt
from bcrypt import migrate

_LONG_PASSWORD = b"correct horse battery staple " * 5

# Generated by bcrypt 4.0.1 (the last release before the strict 72-byte
# limit) with a fixed cost-4 salt. These fixtures are intentionally static so
# the compatibility tests do not depend on the local implementation.
_OLD_BCRYPT_PASSWORD_2A = (
    b"$2a$04$cVWp4XaNU8a4v1uMRum2SOIcv6bg77vANqaCYkTxzO14SrDL4KeYi"
)
_OLD_BCRYPT_LONG_2A = (
    b"$2a$04$cVWp4XaNU8a4v1uMRum2SOg5cEOmXYg8VdNKvdcsMOD26Zz3CfBXa"
)
_OLD_BCRYPT_LONG_2Y = (
    b"$2y$04$cVWp4XaNU8a4v1uMRum2SOg5cEOmXYg8VdNKvdcsMOD26Zz3CfBXa"
)


def _legacy_2a_hash(password: bytes, rounds: int = 4) -> bytes:
    salt = bcrypt.gensalt(rounds, prefix=b"2a")
    return bcrypt.hashpw(password[:72], salt)


def _current_hash(password: bytes, rounds: int = 4) -> bytes:
    return bcrypt.hashpw(password, bcrypt.gensalt(rounds), prehash=True)


def test_prehash_password_is_sha256_base64():
    password = b"\x00long password" * 10
    assert bcrypt.prehash_password(password) == base64.b64encode(
        hashlib.sha256(password).digest()
    )
    assert len(bcrypt.prehash_password(password)) == 44


def test_prehash_password_type():
    with pytest.raises(TypeError):
        bcrypt.prehash_password("password")  # type: ignore[arg-type]


def test_prehash_long_password():
    hashed = bcrypt.hashpw(_LONG_PASSWORD, bcrypt.gensalt(4), prehash=True)

    assert hashed.startswith(b"$2b$04$")
    assert bcrypt.checkpw(_LONG_PASSWORD, hashed)
    assert bcrypt.checkpw(_LONG_PASSWORD, hashed, prehash=True)
    with pytest.raises(ValueError):
        bcrypt.checkpw(
            _LONG_PASSWORD, hashed, prehash=False, legacy_truncate=False
        )


def test_prehash_does_not_change_short_inputs():
    salt = bcrypt.gensalt(4)
    password = b"x" * 72
    assert bcrypt.hashpw(password, salt, prehash=True) == bcrypt.hashpw(
        password, salt
    )


def test_legacy_long_password_truncation_still_verifies():
    legacy_hash = _legacy_2a_hash(_LONG_PASSWORD)

    assert bcrypt.checkpw(_LONG_PASSWORD, legacy_hash) is True
    assert bcrypt.checkpw(_LONG_PASSWORD, legacy_hash, prehash=False) is True
    assert (
        bcrypt.checkpw(
            _LONG_PASSWORD,
            legacy_hash,
            prehash=True,
            legacy_truncate=False,
        )
        is False
    )


@pytest.mark.parametrize(
    "old_hash", [_OLD_BCRYPT_LONG_2A, _OLD_BCRYPT_LONG_2Y]
)
def test_old_bcrypt_long_password_interoperability(old_hash):
    assert bcrypt.checkpw(_LONG_PASSWORD, old_hash)

    verified, new_hash = bcrypt.checkpw_and_upgrade(
        _LONG_PASSWORD, old_hash, rounds=4
    )
    assert verified is True
    assert new_hash is not None
    assert new_hash.startswith(b"$2b$04$")
    assert bcrypt.checkpw(_LONG_PASSWORD, new_hash, legacy_truncate=False)


def test_old_bcrypt_short_password_interoperability():
    assert bcrypt.checkpw(b"password", _OLD_BCRYPT_PASSWORD_2A)


def test_checkpw_strict_long_password_raises():
    legacy_hash = _legacy_2a_hash(_LONG_PASSWORD)
    with pytest.raises(ValueError):
        bcrypt.checkpw(
            _LONG_PASSWORD,
            legacy_hash,
            prehash=False,
            legacy_truncate=False,
        )


def test_needs_update():
    password = b"password"
    old_hash = _legacy_2a_hash(password)
    current_hash = _current_hash(password)

    assert bcrypt.needs_update(old_hash) is True
    assert bcrypt.needs_rehash(old_hash) is True
    assert bcrypt.needs_update(current_hash, rounds=4) is False
    assert bcrypt.needs_update(current_hash) is True
    assert bcrypt.needs_update(current_hash, rounds=12) is True


@pytest.mark.parametrize(
    "hashed_password, rounds, prefix, error",
    [
        (b"not-a-hash", None, b"2b", ValueError),
        (b"$2z$04$" + b"." * 22, None, b"2b", ValueError),
        (b"$2b$4$" + b"." * 22, None, b"2b", ValueError),
        (b"$2b$03$" + b"." * 22, None, b"2b", ValueError),
        (b"$2b$04$short", None, b"2b", ValueError),
        (b"$2b$04$" + b"." * 22, 3, b"2b", ValueError),
        (b"$2b$04$" + b"." * 22, None, b"2c", ValueError),
        ("$2b$04$" + "." * 22, None, b"2b", TypeError),
    ],
)
def test_needs_update_invalid(hashed_password, rounds, prefix, error):
    with pytest.raises(error):
        bcrypt.needs_update(hashed_password, rounds=rounds, prefix=prefix)


def test_checkpw_and_upgrade_short_password():
    password = b"password"
    old_hash = _legacy_2a_hash(password)

    verified, new_hash = bcrypt.checkpw_and_upgrade(
        password, old_hash, rounds=4
    )
    assert verified is True
    assert new_hash is not None
    assert new_hash.startswith(b"$2b$04$")
    assert bcrypt.checkpw(password, new_hash)
    assert bcrypt.checkpw(password, old_hash)

    assert bcrypt.verify_and_upgrade(password, new_hash, rounds=4) == (
        True,
        None,
    )
    assert bcrypt.checkpw_and_upgrade(b"wrong", old_hash, rounds=4) == (
        False,
        None,
    )


def test_checkpw_and_upgrade_long_password():
    old_hash = _legacy_2a_hash(_LONG_PASSWORD)

    verified, new_hash = bcrypt.checkpw_and_upgrade(
        _LONG_PASSWORD, old_hash, rounds=4
    )
    assert verified is True
    assert new_hash is not None
    assert new_hash.startswith(b"$2b$04$")
    assert bcrypt.checkpw(_LONG_PASSWORD, new_hash)
    assert bcrypt.checkpw(_LONG_PASSWORD, new_hash, legacy_truncate=False)
    assert not bcrypt.checkpw(
        _LONG_PASSWORD[:72],
        new_hash,
        prehash=False,
        legacy_truncate=False,
    )


def test_checkpw_and_upgrade_preserves_higher_cost():
    password = b"password"
    old_hash = _legacy_2a_hash(password, rounds=5)

    verified, new_hash = bcrypt.checkpw_and_upgrade(
        password, old_hash, rounds=4
    )
    assert verified is True
    assert new_hash is not None
    assert new_hash.startswith(b"$2b$05$")


def test_checkpw_and_upgrade_without_prehash():
    old_hash = _legacy_2a_hash(_LONG_PASSWORD)

    verified, new_hash = bcrypt.checkpw_and_upgrade(
        _LONG_PASSWORD, old_hash, rounds=4, prehash=False
    )
    assert verified is True
    assert new_hash is not None
    assert bcrypt.checkpw(_LONG_PASSWORD, new_hash, prehash=False)


def test_checkpw_and_upgrade_strict_long_password():
    old_hash = _legacy_2a_hash(_LONG_PASSWORD)
    with pytest.raises(ValueError):
        bcrypt.checkpw_and_upgrade(
            _LONG_PASSWORD,
            old_hash,
            rounds=4,
            prehash=False,
            legacy_truncate=False,
        )


@pytest.mark.parametrize(
    "rounds, prefix",
    [(3, b"2b"), (4, b"2c")],
)
def test_checkpw_and_upgrade_invalid_config(rounds, prefix):
    with pytest.raises(ValueError):
        bcrypt.checkpw_and_upgrade(
            b"password",
            _current_hash(b"password"),
            rounds=rounds,
            prefix=prefix,
        )


def test_upgrade_hash_variants():
    password = b"password"
    old_hash = _legacy_2a_hash(password)
    current_hash = _current_hash(password)

    upgraded = bcrypt.upgrade_hash(password, old_hash, rounds=4)
    assert upgraded is not None
    assert upgraded.startswith(b"$2b$")
    assert (
        bcrypt.upgrade_hash(password, current_hash, rounds=4) == current_hash
    )
    assert bcrypt.upgrade_hash(b"wrong", old_hash, rounds=4) is None

    migrated = bcrypt.migrate_hash(password, old_hash, rounds=4)
    assert migrated is not None
    assert bcrypt.checkpw(password, migrated)


def test_passlib_2a_interoperability():
    passlib_bcrypt = pytest.importorskip("passlib.hash").bcrypt
    password = b"legacy password"

    old_hash = passlib_bcrypt.using(ident="2a", rounds=4).hash(
        password.decode("ascii")
    )
    assert bcrypt.checkpw(password, old_hash.encode("ascii"))

    salt = bcrypt.gensalt(4, prefix=b"2a")
    our_hash = bcrypt.hashpw(password, salt)
    assert passlib_bcrypt.verify(password.decode("ascii"), our_hash.decode())


def test_passlib_long_password_interoperability():
    passlib_bcrypt = pytest.importorskip("passlib.hash").bcrypt
    handler = passlib_bcrypt.using(ident="2a", rounds=4, truncate_error=False)
    old_hash = handler.hash(_LONG_PASSWORD.decode("ascii"))

    assert bcrypt.checkpw(_LONG_PASSWORD, old_hash.encode("ascii"))
    verified, new_hash = bcrypt.checkpw_and_upgrade(
        _LONG_PASSWORD, old_hash.encode("ascii"), rounds=4
    )
    assert verified is True
    assert new_hash is not None
    assert bcrypt.checkpw(_LONG_PASSWORD, new_hash)


def test_manual_prehash_interoperability():
    prehashed = base64.b64encode(hashlib.sha256(_LONG_PASSWORD).digest())
    old_hash = bcrypt.hashpw(prehashed, bcrypt.gensalt(4))

    assert bcrypt.checkpw(_LONG_PASSWORD, old_hash)


def test_migrate_record_upgraded():
    result = migrate.migrate_record(
        {
            "id": "alice",
            "password": "legacy password",
            "hash": _legacy_2a_hash(b"legacy password").decode("ascii"),
        },
        rounds=4,
    )

    assert result["id"] == "alice"
    assert result["status"] == "upgraded"
    assert result["hash"].startswith("$2b$04$")
    assert result["previous_hash"].startswith("$2a$04$")
    assert "password" not in result


def test_migrate_record_unchanged():
    password = b"password"
    hashed = _current_hash(password)
    result = migrate.migrate_record(
        {"password": password, "hash": hashed}, rounds=4
    )
    assert result == {"status": "unchanged", "hash": hashed.decode()}


def test_migrate_record_invalid_password():
    hashed = _legacy_2a_hash(b"password")
    result = migrate.migrate_record(
        {"password": "wrong", "hash": hashed}, rounds=4
    )
    assert result["status"] == "invalid"
    assert result["hash"] == hashed.decode()


def test_migrate_record_password_b64():
    password = b"\xff" * 100
    result = migrate.migrate_record(
        {
            "password_b64": base64.b64encode(password).decode("ascii"),
            "hash": _legacy_2a_hash(password),
        },
        rounds=4,
    )
    assert result["status"] == "upgraded"
    assert bcrypt.checkpw(
        password, result["hash"].encode("ascii"), legacy_truncate=False
    )


@pytest.mark.parametrize(
    "record",
    [
        {},
        {"password": "x", "password_b64": "eA==", "hash": "x"},
        {"password_b64": "***", "hash": "x"},
        {"password_b64": 123, "hash": "x"},
        {"password": 123, "hash": "x"},
        {"password": "x", "hash": 123},
        {"password": "x", "hash": "nonascii-\N{SNOWMAN}"},
        {"password": "x", "hash": "not-a-hash"},
    ],
)
def test_migrate_record_invalid_input(record):
    result = migrate.migrate_record(record, rounds=4)
    assert result["status"] == "invalid"


def test_migrate_record_missing_hash():
    result = migrate.migrate_record({"password": "x"}, rounds=4)
    assert result["status"] == "invalid"
    assert result["hash"] == ""


def test_migrate_record_mapping_type():
    with pytest.raises(TypeError):
        migrate.migrate_record([])  # type: ignore[arg-type]


@pytest.mark.parametrize(
    "rounds, prefix",
    [(3, b"2b"), (4, b"2c")],
)
def test_migrate_record_invalid_config(rounds, prefix):
    with pytest.raises(ValueError):
        migrate.migrate_record({}, rounds=rounds, prefix=prefix)


def test_migrate_cli_files(tmp_path):
    input_path = tmp_path / "input.jsonl"
    output_path = tmp_path / "output.jsonl"
    old_hash = _legacy_2a_hash(b"password")
    input_path.write_text(
        "\n"
        + json.dumps(
            {"id": 1, "password": "password", "hash": old_hash.decode()}
        )
        + "\n",
        encoding="utf-8",
    )

    assert (
        migrate.main(
            [
                str(input_path),
                "--rounds",
                "4",
                "--output",
                str(output_path),
            ]
        )
        == 0
    )
    result = json.loads(output_path.read_text(encoding="utf-8"))
    assert result["id"] == 1
    assert result["status"] == "upgraded"


def test_migrate_cli_stdin_stdout(monkeypatch):
    old_hash = _legacy_2a_hash(b"password")
    input_stream = __import__("io").StringIO(
        json.dumps({"password": "password", "hash": old_hash.decode()}) + "\n"
    )
    output_stream = __import__("io").StringIO()
    monkeypatch.setattr(sys, "stdin", input_stream)
    monkeypatch.setattr(sys, "stdout", output_stream)

    assert migrate.main(["--rounds", "4"]) == 0
    result = json.loads(output_stream.getvalue())
    assert result["status"] == "upgraded"


def test_migrate_cli_invalid_json(capsys):
    input_stream = __import__("io").StringIO("{not json}\n")
    sys.stdin, old_stdin = input_stream, sys.stdin
    try:
        assert migrate.main([]) == 2
    finally:
        sys.stdin = old_stdin
    assert "invalid JSON" in capsys.readouterr().err


def test_migrate_cli_non_object_record(capsys):
    input_stream = __import__("io").StringIO("[]\n")
    sys.stdin, old_stdin = input_stream, sys.stdin
    try:
        assert migrate.main([]) == 2
    finally:
        sys.stdin = old_stdin
    assert "record must be an object" in capsys.readouterr().err


def test_migrate_cli_fail_on_invalid(monkeypatch):
    input_stream = __import__("io").StringIO(
        json.dumps(
            {
                "password": "wrong",
                "hash": _current_hash(b"right").decode("ascii"),
            }
        )
        + "\n"
    )
    output_stream = __import__("io").StringIO()
    monkeypatch.setattr(sys, "stdin", input_stream)
    monkeypatch.setattr(sys, "stdout", output_stream)

    assert migrate.main(["--rounds", "4", "--fail-on-invalid"]) == 1
    assert json.loads(output_stream.getvalue())["status"] == "invalid"


def test_migrate_cli_missing_input_file(capsys):
    assert migrate.main(["/does/not/exist.jsonl"]) == 2
    assert "migration failed" in capsys.readouterr().err


def test_migrate_module_entrypoint(monkeypatch, tmp_path):
    input_path = tmp_path / "input.jsonl"
    output_path = tmp_path / "output.jsonl"
    input_path.write_text(
        json.dumps(
            {
                "password": "password",
                "hash": _legacy_2a_hash(b"password").decode("ascii"),
            }
        )
        + "\n",
        encoding="utf-8",
    )
    monkeypatch.setattr(
        sys,
        "argv",
        [
            "bcrypt.migrate",
            str(input_path),
            "--rounds",
            "4",
            "--output",
            str(output_path),
        ],
    )
    monkeypatch.delitem(sys.modules, "bcrypt.migrate")

    with pytest.raises(SystemExit) as exc_info:
        runpy.run_module("bcrypt.migrate", run_name="__main__")
    assert exc_info.value.code == 0
    assert json.loads(output_path.read_text())["status"] == "upgraded"
